values.customThemeCss:
/* SLIME LAB 1.0 — continuous soft geometry, no layout or hit-target movement. */
@property --slime-a {
  syntax: '<percentage>';
  inherits: false;
  initial-value: 25%;
}
@property --slime-b {
  syntax: '<percentage>';
  inherits: false;
  initial-value: 38%;
}
@property --slime-c {
  syntax: '<percentage>';
  inherits: false;
  initial-value: 30%;
}
@property --slime-d {
  syntax: '<percentage>';
  inherits: false;
  initial-value: 44%;
}
@property --slime-wa {
  syntax: '<length>';
  inherits: false;
  initial-value: 24px;
}
@property --slime-wb {
  syntax: '<length>';
  inherits: false;
  initial-value: 42px;
}
:root {
  --slime-speed: 1;
  --accent: #146747;
  --accent-hover: #1b845a;
  --text-primary: #15382b;
  --text-secondary: #426253;
  --text-link: #125c40;
  --border: #87cba1;
  --background: #e7ffed;
  --background-alt: #dcffe7;
  --elevation-01: #dcffe7;
  --elevation-02: #f0fff4;
  --elevation-03: #e3ffeb;
  --sidebar-layout-content-background-color: transparent;
  --accent-pale: transparent;
  --tui-background-base: #f0fff4;
  --tui-text-primary: #15382b;
  --tui-text-secondary: #426253;
  --tui-text-action: #146747;
  --tui-background-accent-1: #146747;
}
html body {
  color: #15382b !important;
  font-family: Arial, sans-serif !important;
  background: #c5f487 !important;
}
html body :is(cu-sidebar-layout, .culms-bg-canvas, .layout, main.main, .sidebar__content, .main) {
  background-image:
    radial-gradient(ellipse at 16% 12%, #e5ffb0 0, transparent 52%),
    radial-gradient(ellipse at 88% 75%, #55d2a2 0, transparent 48%),
    linear-gradient(130deg, #bde997, #b9f3df) !important;
  background-attachment: fixed !important;
  background-size: cover !important;
}
html
  body
  :is(
    .header-island,
    .exam-panel,
    .course-list__item,
    .card,
    .slime-window,
    cu-course-card,
    .course-section,
    .content-block,
    cu-profile,
    tui-dialog,
    .t-dialog,
    .culms-modal,
    .culms-friends-modal,
    [data-culms-island]
  ) {
  background: rgba(244, 255, 245, 0.91) !important;
  color: #15382b !important;
  border: 1px solid #87cba1 !important;
  box-shadow:
    0 12px 32px #247d4930,
    inset 0 2px 0 #ffffffc9 !important;
  border-radius: var(--slime-wa) var(--slime-wb) calc(var(--slime-wa) + 10px)
    calc(var(--slime-wb) - 8px) / var(--slime-wb) var(--slime-wa) calc(var(--slime-wb) - 6px)
    calc(var(--slime-wa) + 8px) !important;
  animation: slime-windows calc(9s / var(--slime-speed)) ease-in-out infinite alternate !important;
}
html body :is(.course-list__item, .slime-window, .content-block):nth-child(2n) {
  animation-delay: -4s !important;
  animation-direction: alternate-reverse !important;
}
html body :is(.course-list__item, .slime-window, .content-block):nth-child(3n) {
  animation-delay: -7s !important;
}
html
  body
  :is(button, a[tuiButton], a[tuiIconButton], input[type='submit'], input[type='button']):not(
    [data-culms-shape-exempt]
  ) {
  clip-path: none !important;
  border: 1px solid #2d8058 !important;
  border-radius: var(--slime-a) var(--slime-b) var(--slime-c) var(--slime-d) / var(--slime-d)
    var(--slime-c) var(--slime-a) var(--slime-b) !important;
  animation: slime-buttons calc(6s / var(--slime-speed)) ease-in-out infinite alternate !important;
  background: linear-gradient(125deg, #1e7a50, #14593c) !important;
  color: #fff !important;
  box-shadow:
    inset 0 2px 0 #ffffff45,
    0 5px 12px #2f785a25 !important;
  min-height: 36px !important;
  white-space: normal !important;
  overflow-wrap: anywhere;
}
html body :is(button, a[tuiButton], a[tuiIconButton]):nth-of-type(2n) {
  animation-delay: -2.8s !important;
  animation-direction: alternate-reverse !important;
}
html body :is(button, a[tuiButton], a[tuiIconButton]):focus-visible {
  outline: 3px solid #123d2a !important;
  outline-offset: 4px !important;
}
html body :is(.header, header, .sidebar, .static-content) {
  background: #e7ffed !important;
  color: #15382b !important;
}
html body :is(input, textarea, select) {
  background: #f5fff8 !important;
  color: #15382b !important;
  border: 1px solid #87cba1 !important;
}
html
  body
  :is(.course-copy, .course-copy h2, .course-copy p, .page-title, .subline, .culms-old-title) {
  color: #15382b !important;
}
html body :is(.culms-cover, .course-cover) {
  background:
    radial-gradient(ellipse at 25% 15%, #f5ffaf 0, transparent 60%),
    linear-gradient(135deg, #90d988, #4abf91) !important;
}
html body :is(.tab.active, .cu-navtab__main-element_active) {
  background: #d3f586 !important;
  color: #15382b !important;
}
@keyframes slime-buttons {
  0% {
    --slime-a: 22%;
    --slime-b: 42%;
    --slime-c: 30%;
    --slime-d: 46%;
  }
  50% {
    --slime-a: 42%;
    --slime-b: 27%;
    --slime-c: 46%;
    --slime-d: 25%;
  }
  100% {
    --slime-a: 30%;
    --slime-b: 48%;
    --slime-c: 25%;
    --slime-d: 38%;
  }
}
@keyframes slime-windows {
  0% {
    --slime-wa: 22px;
    --slime-wb: 44px;
  }
  50% {
    --slime-wa: 42px;
    --slime-wb: 27px;
  }
  100% {
    --slime-wa: 28px;
    --slime-wb: 48px;
  }
}
html.slime-paused
  body
  :is(
    button,
    a[tuiButton],
    a[tuiIconButton],
    input[type='submit'],
    input[type='button'],
    .header-island,
    .exam-panel,
    .course-list__item,
    .card,
    .slime-window,
    cu-course-card,
    .course-section,
    .content-block,
    cu-profile,
    tui-dialog,
    .t-dialog,
    .culms-modal,
    .culms-friends-modal,
    [data-culms-island]
  ) {
  animation-play-state: paused !important;
}
@media (prefers-reduced-motion: reduce) {
  html
    body
    :is(
      button,
      a[tuiButton],
      a[tuiIconButton],
      input[type='submit'],
      input[type='button'],
      .header-island,
      .exam-panel,
      .course-list__item,
      .card,
      .slime-window,
      cu-course-card,
      .course-section,
      .content-block,
      cu-profile,
      tui-dialog,
      .t-dialog,
      .culms-modal,
      .culms-friends-modal,
      [data-culms-island]
    ) {
    animation: none !important;
  }
}
/* A course has one outer window; do not draw a second window inside it. */
html body ul.course-list.culms-old-design cu-course-card.course-list__card {
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
  border-radius: 0 !important;
  animation: none !important;
}
/* Actual amorphous surfaces: SVG displacement affects paint, not labels. */
:root {
  --culms-slime-active: 1;
}
html
  body
  :is(button, a[tuiButton], a[tuiIconButton], input[type='submit'], input[type='button']):not(
    [data-culms-shape-exempt]
  ) {
  position: relative !important;
  isolation: isolate !important;
  overflow: visible !important;
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
  border-radius: 20px !important;
  animation: none !important;
}
html body :is(button, a[tuiButton], a[tuiIconButton]):not([data-culms-shape-exempt])::after {
  content: '' !important;
  position: absolute !important;
  inset: -7px -12px !important;
  z-index: -1 !important;
  pointer-events: none !important;
  background:
    radial-gradient(ellipse at 35% 12%, #a8e87466, transparent 56%),
    linear-gradient(140deg, #21794c, #0e5338) !important;
  border: 1px solid #65b77f !important;
  box-shadow:
    inset 0 4px 12px #dcffbd66,
    0 8px 14px #174c3444 !important;
  border-radius: 43% 27% 37% 22%/35% 48% 26% 42% !important;
  filter: url('#culms-slime-button-filter') !important;
  animation: slime-surface calc(6s / var(--slime-speed)) ease-in-out infinite alternate !important;
}
html
  body
  :is(
    .header-island,
    .exam-panel,
    .course-list__item,
    .card,
    .slime-window,
    .course-section,
    .content-block,
    cu-profile,
    tui-dialog,
    .t-dialog,
    .culms-modal,
    .culms-friends-modal,
    [data-culms-island]
  ) {
  position: relative;
  isolation: isolate !important;
  overflow: visible !important;
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
}
html
  body
  :is(
    .header-island,
    .exam-panel,
    .course-list__item,
    .card,
    .slime-window,
    .course-section,
    .content-block,
    cu-profile,
    tui-dialog,
    .t-dialog,
    .culms-modal,
    .culms-friends-modal,
    [data-culms-island]
  )::before {
  content: '';
  position: absolute;
  inset: -6px;
  z-index: -1;
  pointer-events: none;
  background: linear-gradient(140deg, #f6ffed, #defbe4);
  box-shadow:
    inset 0 4px 15px #fff,
    0 16px 28px #205b3833;
  border: 1px solid #85d49b;
  border-radius: 18% 11% 16% 12%/10% 17% 9% 14%;
  filter: url('#culms-slime-window-filter');
  animation: slime-surface calc(10s / var(--slime-speed)) ease-in-out infinite alternate;
}
html body .course-list__item:nth-child(2n)::before {
  animation-delay: -4s;
  animation-direction: alternate-reverse;
}
html body button:nth-of-type(2n)::after {
  animation-delay: -3s !important;
  animation-direction: alternate-reverse !important;
}
@keyframes slime-surface {
  0% {
    transform: scale(1.02, 0.96) rotate(-1.2deg);
    border-radius: 42% 24% 35% 20%/25% 44% 22% 38%;
  }
  50% {
    transform: scale(0.96, 1.06) rotate(1.5deg);
    border-radius: 25% 43% 20% 38%/43% 25% 37% 20%;
  }
  100% {
    transform: scale(1.04, 0.98) rotate(-0.8deg);
    border-radius: 36% 22% 45% 26%/20% 37% 28% 46%;
  }
}
html.slime-paused body *::before,
html.slime-paused body *::after {
  animation-play-state: paused !important;
}
@media (prefers-reduced-motion: reduce) {
  html body *::before,
  html body *::after {
    animation: none !important;
    filter: none !important;
  }
}
/* Each moving surface is strictly contained in its own layout box. */
:root {
  --slime-speed: 0.35;
}
html body :is(button, a[tuiButton], a[tuiIconButton]):not([data-culms-shape-exempt]) {
  contain: paint !important;
  overflow: hidden !important;
  isolation: isolate !important;
  border-radius: 0 !important;
  padding: 18px 32px !important;
  min-height: 58px !important;
  line-height: 1.3 !important;
  box-sizing: border-box !important;
  margin: 4px !important;
}
html body :is(button, a[tuiButton], a[tuiIconButton]):not([data-culms-shape-exempt])::after {
  inset: 10px 14px !important;
  box-shadow: inset 0 3px 10px #dcffbd66 !important;
}
html
  body
  :is(
    .header-island,
    .exam-panel,
    .course-list__item,
    .card,
    .slime-window,
    .course-section,
    .content-block,
    cu-profile,
    tui-dialog,
    .t-dialog,
    .culms-modal,
    .culms-friends-modal,
    [data-culms-island]
  ) {
  contain: paint !important;
  overflow: hidden !important;
}
html
  body
  :is(
    .header-island,
    .exam-panel,
    .course-list__item,
    .card,
    .slime-window,
    .course-section,
    .content-block,
    cu-profile,
    tui-dialog,
    .t-dialog,
    .culms-modal,
    .culms-friends-modal,
    [data-culms-island]
  )::before {
  inset: 12px !important;
  box-shadow: inset 0 4px 15px #fff !important;
}
